const $ = (sel) => document.querySelector(sel);

const examples = [
  {w:"νοθος", place:false},
  {w:"ποθος", place:false},
  {w:"ψοθος", place:false},
  {w:"ροθος", place:false},
  {w:"μοθος", place:false},
  {w:"λιθος", place:false},
  {w:"πιθος", place:false},
  {w:"ζυθος", place:false},
  {w:"γνυθος", place:false},
  {w:"βυθος", place:true},
  {w:"ξανθος", place:false},
  {w:"τυτθος", place:false},
  {w:"αιθος", place:false},
  {w:"λοισθος", place:false},
  {w:"Σκιαθος", place:true},
  {w:"Κραπαθος", place:true},
  {w:"καλαθος", place:false},
  {w:"κυαθος", place:false},
  {w:"λαπαθος", place:false},
  {w:"ψαμαθος", place:false},
  {w:"ορμαθος", place:false},
  {w:"γυργαθος", place:false},
  {w:"Παρθος", place:true}
];

const tonosMap = {
  "α":"ά","ε":"έ","η":"ή","ι":"ί","ο":"ό","υ":"ύ","ω":"ώ",
  "Α":"Ά","Ε":"Έ","Η":"Ή","Ι":"Ί","Ο":"Ό","Υ":"Ύ","Ω":"Ώ"
};

function stripAccents(s){
  // Remove common Greek tonos/dialytika-tonos; keep diaeresis.
  return s
    .replace(/[άὰᾶἀἁἄἅἂἃἆἇᾱᾰ]/g,"α")
    .replace(/[έὲἐἑἔἕἒἓ]/g,"ε")
    .replace(/[ήὴῆἠἡἤἥἢἣἦἧ]/g,"η")
    .replace(/[ίὶῖἰἱἴἵἲἳἶἷϊΐ]/g,(m)=> (m==="ϊ"||m==="ΐ")?"ϊ":"ι")
    .replace(/[όὸὀὁὄὅὂὃ]/g,"ο")
    .replace(/[ύὺῦὐὑὔὕὒὓὖὗϋΰ]/g,(m)=> (m==="ϋ"||m==="ΰ")?"ϋ":"υ")
    .replace(/[ώὼῶὠὡὤὥὢὣὦὧ]/g,"ω");
}

function isVowel(ch){
  return "αεηιουωΑΕΗΙΟΥΩάέήίόύώϊϋΐΰ".includes(ch);
}

function roughSyllables(word){
  // Very rough: split before each vowel group.
  const w = word;
  let syl = [];
  let cur = "";
  for(let i=0;i<w.length;i++){
    const ch = w[i];
    cur += ch;
    const next = w[i+1];
    if(isVowel(ch)){
      // keep diphthongs together (αι, ει, οι, υι, αυ, ευ, ου, ηυ)
      const pair = ch + (next||"");
      const diph = ["αι","ει","οι","υι","αυ","ευ","ου","ηυ","ΑΙ","ΕΙ","ΟΙ","ΥΙ","ΑΥ","ΕΥ","ΟΥ","ΗΥ"];
      if(next && diph.includes(pair)){
        cur += next;
        i++;
      }
      // end syllable after vowel group
      syl.push(cur);
      cur = "";
    }
  }
  if(cur) syl[syl.length-1] = (syl[syl.length-1]||"") + cur;
  return syl.filter(x=>x.length);
}

function accentOnSyllable(word, sylIndexFromEnd){
  // sylIndexFromEnd: 1=ultima,2=penult,3=antepenult
  const syl = roughSyllables(word);
  if(syl.length===0) return {form:word, syl};
  const idx = syl.length - sylIndexFromEnd;
  const target = Math.max(0, Math.min(syl.length-1, idx));

  // Find last vowel in that syllable and add tonos.
  let s = syl[target];
  let pos = -1;
  for(let i=s.length-1;i>=0;i--){
    if(isVowel(s[i])){ pos=i; break; }
  }
  if(pos>=0){
    const ch = s[pos];
    const base = stripAccents(ch);
    const accented = tonosMap[base] || ch;
    s = s.slice(0,pos) + accented + s.slice(pos+1);
    syl[target] = s;
  }
  return {form:syl.join(""), syl};
}

function startsLongish(word){
  // Toy heuristic: treat initial η/ω or initial diphthong as "long".
  const w = word;
  const first = w[0]||"";
  const second = w[1]||"";
  const diph = ["αι","ει","οι","υι","αυ","ευ","ου","ηυ","ΑΙ","ΕΙ","ΟΙ","ΥΙ","ΑΥ","ΕΥ","ΟΥ","ΗΥ"];
  if(first==="η"||first==="ω"||first==="Η"||first==="Ω") return true;
  if(diph.includes(first+second)) return true;
  return false;
}

function penultLooksLong(word){
  // Toy heuristic: if penult syllable contains η/ω or a diphthong, call it long.
  const syl = roughSyllables(word);
  if(syl.length<2) return false;
  const pen = syl[syl.length-2];
  const hasEtaOmega = /[ηωΗΩ]/.test(pen);
  const hasDiph = /(αι|ει|οι|υι|αυ|ευ|ου|ηυ|ΑΙ|ΕΙ|ΟΙ|ΥΙ|ΑΥ|ΕΥ|ΟΥ|ΗΥ)/.test(pen);
  return hasEtaOmega || hasDiph;
}

function precededBySigmaBeforeThos(word){
  // check ...σθος ending
  return /σθος$/i.test(word);
}

function analyzeWord(raw){
  const ignore = $("#strip").checked;
  const asPlace = $("#place").checked;
  let w = raw.trim();
  if(!w) return null;
  if(ignore) w = stripAccents(w);

  const lower = w.toLowerCase();
  const isAthos = lower.endsWith("αθος");
  const isThos = lower.endsWith("θος");

  let rule = "";
  let target = 2; // default penult

  if(isAthos){
    const syl = roughSyllables(w);
    const tri = syl.length>=3;
    if(tri && !startsLongish(w)){
      target = 3;
      rule = "-αθος (trisyllabic, starts short) → accent on antepenult (προπαροξύτονον), per Herodian.";
    } else {
      target = 1;
      rule = "-αθος but starts long (toy heuristic) → often oxytone (ultima), like ὁρμαθός / γυργαθός.";
    }
  } else if(isThos){
    const syl = roughSyllables(w);
    const disyll = syl.length===2;

    if(asPlace){
      // Herodian: exception for place-names; we just flag and shift to ultima as a playful contrast.
      target = 1;
      rule = "Marked as place-name: Herodian notes exceptions (‘unless it denotes a place’). Toy suggests shifting toward an oxytone (ultima).";
    } else if(disyll && penultLooksLong(w) && !precededBySigmaBeforeThos(w)){
      target = 1;
      rule = "Disyllabic -θος with long penult (and no σ before -θος) → accent on ultima (ὀξύτονον): e.g. ξανθός, τυτθός, αἰθός.";
    } else {
      target = 2;
      rule = "-θος with two short syllables (toy default) → accent on penult (παροξύτονον): e.g. νόθος, πόθος, λίθος, ζύθος.";
      if(disyll===false) rule += " (Input isn’t clearly disyllabic; still applying the ‘penult’ default.)";
      if(precededBySigmaBeforeThos(w)) rule += " Note: words like λοῖσθος have σ before -θος; Herodian flags this.";
    }
  } else {
    target = 2;
    rule = "Not an -θος / -αθος ending. Toy will just accent the penult as a fallback.";
  }

  const acc = accentOnSyllable(w, target);
  return {
    base:w,
    suggested: acc.form,
    syllables: acc.syl,
    rule
  };
}

function render(res){
  if(!res){
    $("#suggest").textContent = "—";
    $("#rule").textContent = "—";
    $("#syll").textContent = "—";
    return;
  }
  $("#suggest").textContent = res.suggested;
  $("#rule").textContent = res.rule;
  $("#syll").textContent = res.syllables.join(" · ");
}

function run(){
  const raw = $("#inp").value;
  render(analyzeWord(raw));
}

$("#analyze").addEventListener("click", run);
$("#inp").addEventListener("keydown", (e)=>{ if(e.key==="Enter") run(); });
$("#strip").addEventListener("change", run);
$("#place").addEventListener("change", run);

$("#clear").addEventListener("click", ()=>{
  $("#inp").value = "";
  $("#place").checked = false;
  render(null);
  $("#inp").focus();
});

$("#random").addEventListener("click", ()=>{
  const ex = examples[Math.floor(Math.random()*examples.length)];
  $("#inp").value = ex.w;
  $("#place").checked = !!ex.place;
  run();
  $("#inp").focus();
});

// Seed with a default example
$("#inp").value = "ξανθος";
run();

